const canvas = document.getElementById("scene");
const ctx = canvas.getContext("2d");
const statusEl = document.getElementById("status");

// geometry: floor f (1..5) slab top y
function floorY(f) { return 580 - (f - 1) * 100; }

// deterministic state machine, driven by a virtual clock in ms
let t = 0;
const STEP = 16.7; // ~60fps
const MOVE_MS = 2000;   // full floor-to-floor move (adjacent floors scaled)
const DOOR_MS = 800;

// phases: open1, close1, move4, open4, close4, move1
let phase = "open1";
let doorT = 0;      // 0..1 progress of current timed sub-phase
let carFloor = 1;   // logical floor (float while moving)

function phaseDuration(p) {
  if (p === "move4") return MOVE_MS * 3;
  if (p === "move1") return MOVE_MS * 3;
  return DOOR_MS;
}

function nextPhase(p) {
  switch (p) {
    case "open1": return "close1";
    case "close1": return "move4";
    case "move4": return "open4";
    case "open4": return "close4";
    case "close4": return "move1";
    case "move1": return "open1";
  }
}

// passenger: waits at floor 1, boards during open1->close1, rides to 4, exits during open4->close4
let paxState = "wait"; // wait | board | ride | exit | pause
let paxT = 0;          // progress within current sub-state

function tickPax(dt) {
  const d = Math.min(doorT, 1);
  switch (paxState) {
    case "wait":
      if (phase === "close1") { paxState = "board"; paxT = 0; }
      break;
    case "board":
      // walk from landing into car during close1
      paxT = d;
      if (phase !== "close1") { paxState = "ride"; }
      break;
    case "ride":
      if (phase === "open4") { paxState = "exit"; paxT = 0; }
      break;
    case "exit":
      // walk out of car during close4
      paxT = d;
      if (phase !== "close4") { paxState = "pause"; paxT = 0; }
      break;
    case "pause":
      if (phase === "open1" && doorT > 0.5) { paxState = "wait"; paxT = 0; }
      break;
  }
}

function tick(dt) {
  t += dt;
  doorT += dt / phaseDuration(phase);
  if (doorT >= 1) {
    doorT = 0;
    phase = nextPhase(phase);
  }
  // car position
  const d = Math.min(doorT, 1);
  switch (phase) {
    case "open1": case "close1": carFloor = 1; break;
    case "move4": carFloor = 1 + 3 * d; break;
    case "open4": case "close4": carFloor = 4; break;
    case "move1": carFloor = 4 - 3 * d; break;
  }
  tickPax(dt);
}

function doorOpenAmount() {
  if (phase === "open1" || phase === "open4") return Math.min(doorT, 1);
  if (phase === "close1" || phase === "close4") return 1 - Math.min(doorT, 1);
  return 0;
}

// car geometry helpers
function carRect() {
  const bx = 60, bw = 360;
  const sx = bx + 240, sw = 80;
  const carW = 72, carH = 60;
  return { x: sx + (sw - carW) / 2, y: floorY(carFloor) - carH, w: carW, h: carH };
}

function paxPos() {
  const c = carRect();
  const doorX = c.x + c.w / 2; // doorway center
  const landX = c.x - 40;      // waiting spot on landing (left of shaft)
  switch (paxState) {
    case "wait": return { x: landX, y: floorY(1), inCar: false };
    case "board": return { x: landX + (doorX - landX) * paxT, y: floorY(1), inCar: paxT > 0.6 };
    case "ride": return { x: doorX, y: floorY(carFloor), inCar: true };
    case "exit": return { x: doorX + (landX - doorX) * paxT, y: floorY(4), inCar: paxT < 0.6 };
    case "pause": return { x: landX, y: floorY(4), inCar: false };
  }
}

function drawPax() {
  const p = paxPos();
  ctx.fillStyle = "#c33";
  // simple person: head + body
  ctx.beginPath();
  ctx.arc(p.x, p.y - 26, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(p.x - 4, p.y - 21, 8, 21);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const bx = 60, bw = 360, floorH = 100;
  for (let f = 1; f <= 5; f++) {
    const y = floorY(f);
    ctx.fillStyle = "#ddd";
    ctx.fillRect(bx, y - floorH + 20, bw, floorH - 20);
    ctx.fillStyle = "#888";
    ctx.fillRect(bx, y, bw, 12);
    ctx.fillStyle = "#333";
    ctx.fillText("Floor " + f, bx + 8, y - floorH / 2);
  }
  ctx.fillStyle = "#666";
  ctx.fillRect(bx - 10, floorY(5) - floorH, bw + 20, 14);

  // shaft
  const sx = bx + 240, sw = 80;
  ctx.strokeStyle = "#c33";
  ctx.strokeRect(sx, floorY(5) - floorH + 14, sw, 5 * floorH - 14);

  // car: top of car sits on slab of current (fractional) floor
  const c = carRect();
  ctx.fillStyle = "#39f";
  ctx.fillRect(c.x, c.y, c.w, c.h);

  // passenger inside car drawn before doors so they appear behind panels
  if (paxPos().inCar) drawPax();

  // doors: two panels sliding apart by open amount
  const open = doorOpenAmount();
  const panelW = (c.w / 2) * (1 - open);
  ctx.fillStyle = "#15a";
  ctx.fillRect(c.x, c.y + 4, panelW, c.h - 8);
  ctx.fillRect(c.x + c.w - panelW, c.y + 4, panelW, c.h - 8);

  // passenger outside car drawn after doors
  if (!paxPos().inCar) drawPax();

  statusEl.textContent = phase + " | floor " + Math.round(carFloor * 10) / 10;
}

const testMode = new URLSearchParams(location.search).get("test") === "1";
if (testMode) {
  // run one full cycle synchronously: 6 phases, each needs >1.0 of doorT
  for (let i = 0; i < 700; i++) tick(STEP);
  draw();
} else {
  let last = performance.now();
  function frame(now) {
    const dt = Math.min(now - last, 100);
    last = now;
    tick(dt);
    draw();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}
</script>
</body>
</html>
