    case "exit": return { x: doorX + (landX - doorX) * paxT, y: SLAB_TOP(4), inCar: paxT < 0.6 };
    case "pause": return { x: landX, y: SLAB_TOP(4), inCar: false };
  }
}

function drawPax() {
  const p = paxPos();
  ctx.fillStyle = "#c33";
