  ctx.beginPath();
  ctx.arc(p.x, p.y - 26, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(p.x - 4, p.y - 21, 8, 21);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // building: five interior stories between ground slab (floor 1) and roof above floor 5
  for (let f = 1; f <= FLOORS; f++) {
    const y = SLAB_TOP(f);
    ctx.fillStyle = "#ddd";
    if (f < FLOORS) ctx.fillRect(BUILDING_X, y - 80, BUILDING_W, 80); // wall above each slab up to next slab
    ctx.fillStyle = "#888";
    ctx.fillRect(BUILDING_X, y, BUILDING_W, 12); // floor slab
    ctx.fillStyle = "#333";
    ctx.fillText("Floor " + f, BUILDING_X + 8, y - 40);
  }
  // roof above the highest interior floor (floor 5)
  ctx.fillStyle = "#666";
  ctx.fillRect(BUILDING_X - 10, SLAB_TOP(FLOORS) - 92, BUILDING_W + 20, 14);

  // shaft: from just below roof to the ground slab of floor 1
  ctx.strokeStyle = "#c33";
  ctx.strokeRect(SHAFT_X, SLAB_TOP(FLOORS) - 80, SHAFT_W, (FLOORS - 1) * 100 + 80);

  // car: top of car sits on slab of current (fractional) floor
  const c = carRect();
  ctx.fillStyle = "#39f";
  ctx.fillRect(c.x, c.y, c.w, c.h);

  // passenger inside car drawn before doors so they appear behind panels
  if (paxPos().inCar) drawPax();

  // doors: two panels sliding apart by open amount
  const open = doorOpenAmount();
  const panelW = (c.w / 2) * (1 - open);
  ctx.fillStyle = "#15a";
  ctx.fillRect(c.x, c.y + 4, panelW, c.h - 8);
  ctx.fillRect(c.x + c.w - panelW, c.y + 4, panelW, c.h - 8);

