const SLAB_TOP = (f) => BASE_Y - (f - 1) * FLOOR_H;   // floor 1 -> 620, floor 5 -> 220
const CAR_H = 60;
const SHAFT_X = 300, SHAFT_W = 80;        // shaft spans full building height
