let phase = "open1";
let doorT = 0;      // 0..1 progress of current timed sub-phase
let carFloor = 1;   // logical floor (float while moving)

function phaseDuration(p) {
  if (p === "move4") return MOVE_MS * 3;
  if (p === "move1") return MOVE_MS * 3;
  return DOOR_MS;
}

function nextPhase(p) {
  switch (p) {
    case "open1": return "close1";
    case "close1": return "move4";
    case "move4": return "open4";
    case "open4": return "close4";
    case "close4": return "move1";
    case "move1": return "open1";
  }
}

// passenger: waits at floor 1, boards during open1->close1, rides to 4, exits during open4->close4
let paxState = "wait"; // wait | board | ride | exit | pause
let paxT = 0;          // progress within current sub-state

function tickPax(dt) {
  const d = Math.min(doorT, 1);
  switch (paxState) {
    case "wait":
      if (phase === "close1") { paxState = "board"; paxT = 0; }
      break;
    case "board":
      // walk from landing into car during close1 — horizontal only, on floor-1 slab
      paxT = d;
      if (phase !== "close1") { paxState = "ride"; }
      break;
    case "ride":
      // vertical only: locked to the car's current floor while inside
      if (phase === "open4") { paxState = "exit"; paxT = 0; }
      break;
    case "exit":
      // walk out of car during close4 — horizontal only, on floor-4 slab
      paxT = d;
      if (phase !== "close4") { paxState = "pause"; paxT = 0; }
      break;
    case "pause":
      if (phase === "open1" && doorT > 0.5) { paxState = "wait"; paxT = 0; }
      break;
  }
}

function tick(dt) {
  t += dt;
  doorT += dt / phaseDuration(phase);
  if (doorT >= 1) {
    doorT = 0;
    phase = nextPhase(phase);
  }
  // car position: car floor rests exactly on the slab of its current (fractional) floor
  const d = Math.min(doorT, 1);
  switch (phase) {
    case "open1": case "close1": carFloor = 1; break;
    case "move4": carFloor = 1 + 3 * d; break;
    case "open4": case "close4": carFloor = 4; break;
    case "move1": carFloor = 4 - 3 * d; break;
  }
  tickPax(dt);
}

function doorOpenAmount() {
  if (phase === "open1" || phase === "open4") return Math.min(doorT, 1);
  if (phase === "close1" || phase === "close4") return 1 - Math.min(doorT, 1);
  return 0;
}

// car geometry helpers — all stops derived from SLAB_TOP so floors/shaft/car agree
function carRect() {
  const carW = SHAFT_W - 8;
  return { x: SHAFT_X + 4, y: SLAB_TOP(carFloor) - CAR_H, w: carW, h: CAR_H };
}

// Passenger motion rules:
//  - horizontal movement ONLY during board (floor-1 slab) and exit (floor-4 slab)
//  - vertical movement ONLY while riding inside the car (y locked to SLAB_TOP(carFloor))
function paxPos() {
  const c = carRect();
  const doorX = c.x + c.w / 2; // doorway center
  const landX = SHAFT_X - 40;  // waiting spot on landing (left of shaft)
  switch (paxState) {
    case "wait": return { x: landX, y: SLAB_TOP(1), inCar: false };
    case "board": return { x: landX + (doorX - landX) * paxT, y: SLAB_TOP(1), inCar: paxT > 0.6 };
    case "ride": return { x: doorX, y: SLAB_TOP(carFloor), inCar: true };
    case "exit": return { x: doorX + (landX - doorX) * paxT, y: SLAB_TOP(4), inCar: paxT < 0.6 };
    case "pause": return { x: landX, y: SLAB_TOP(4), inCar: false };
  }
}

function drawPax() {
  const p = paxPos();
  ctx.fillStyle = "#c33";
  // simple person: head + body standing on the slab (feet at p.y)
  ctx.beginPath();
  ctx.arc(p.x, p.y - 26, 5, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillRect(p.x - 4, p.y - 21, 8, 21);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // building: five interior stories between the ground slab (floor 1) and roof above floor 5
  for (let f = 1; f <= FLOORS; f++) {
    const y = SLAB_TOP(f);
    if (f < FLOORS) {
      ctx.fillStyle = "#ddd";
      ctx.fillRect(BUILDING_X, y - FLOOR_H + 20, BUILDING_W, FLOOR_H - 20); // wall above each slab up to next slab
    }
    ctx.fillStyle = "#888";
    ctx.fillRect(BUILDING_X, y, BUILDING_W, 12); // floor slab
    ctx.fillStyle = "#333";
    ctx.fillText("Floor " + f, BUILDING_X + 8, y - FLOOR_H / 2);
  }
  // roof above the highest interior floor (floor 5)
  ctx.fillStyle = "#666";
  ctx.fillRect(BUILDING_X - 10, SLAB_TOP(FLOORS) - FLOOR_H + 20, BUILDING_W + 20, 14);

  // shaft: from just below roof down to the ground slab of floor 1 (no basement)
  ctx.strokeStyle = "#c33";
  ctx.strokeRect(SHAFT_X, SLAB_TOP(FLOORS) - FLOOR_H + 20, SHAFT_W, (FLOORS - 1) * FLOOR_H);

  // car: top of car sits on slab of current (fractional) floor
  const c = carRect();
  ctx.fillStyle = "#39f";
  ctx.fillRect(c.x, c.y, c.w, c.h);

  // passenger inside car drawn before doors so they appear behind panels
  if (paxPos().inCar) drawPax();

  // doors: two panels sliding apart by open amount
  const open = doorOpenAmount();
  const panelW = (c.w / 2) * (1 - open);
  ctx.fillStyle = "#15a";
  ctx.fillRect(c.x, c.y + 4, panelW, c.h - 8);
  ctx.fillRect(c.x + c.w - panelW, c.y + 4, panelW, c.h - 8);

  // passenger outside car drawn after doors
  if (!paxPos().inCar) drawPax();

  statusEl.textContent = phase + " | floor " + Math.round(carFloor * 10) / 10;
}

const testMode = new URLSearchParams(location.search).get("test") === "1";
if (testMode) {
  // run one full cycle synchronously: 6 phases, each needs >1.0 of doorT
  for (let i = 0; i < 700; i++) tick(STEP);
  draw();
  statusEl.textContent = "ELEVATOR_SMOKE_PASS";
} else {
  let last = performance.now();
  function frame(now) {
