function initDispatch() {
  const floors = [1, 2, 3, 4, 5];
  emptyFloor = floors[Math.floor(rand() * FLOORS)];
  waiting = {};
  for (const f of floors) {
    if (f === emptyFloor) continue;
    waiting[f] = 1; // one person per populated floor
  }
}

edits.oldText:
const floorsWithPeople = Object.keys(waiting).map(Number);
if (!floorsWithPeople.length) return false;
// choose one waiting person at random (across all populated floors)
let f, idx;
do {
  f = floorsWithPeople[Math.floor(rand() * floorsWithPeople.length)];
  idx = Math.floor(rand() * waiting[f].length);
} while (f === emptyFloor); // pickup must differ from destination
const person = waiting[f].splice(idx, 1)[0];
if (!waiting[f].length) delete waiting[f];
pickupFloor = f;
dropFloor = emptyFloor;
tripsDone++;
return true;

