case "closeDrop": {
  // delivery complete: person joins the destination floor; source becomes empty
  waiting[dropFloor] = (waiting[dropFloor] || []).concat([pickupFloor]); // id reused as token
  emptyFloor = pickupFloor;
  return pickNextTrip() ? "movePickup" : "idle";
}

