    case "idle": return pickNextTrip() ? "movePickup" : "idle";
    case "movePickup": return "openPickup";
    case "openPickup": return "closePickup";
    case "closePickup": return "ride";
    case "ride": return "openDrop";
    case "openDrop": return "closeDrop";
    case "closeDrop": {
