  for (let f = 1; f <= FLOORS; f++) {
    const y = SLAB_TOP(f);
    if (f < FLOORS) {
      ctx.fillStyle = "#262b38";
      ctx.fillRect(BUILDING_X, y - FLOOR_H + 20, BUILDING_W, FLOOR_H - 20); // wall above each slab up to next slab
    }
    ctx.fillStyle = "#4a5165";
    ctx.fillRect(BUILDING_X, y, BUILDING_W, 12); // floor slab
    ctx.fillStyle = "#aab2c8";
    ctx.font = "13px 'Segoe UI', system-ui, sans-serif";
    ctx.fillText("Floor " + f, BUILDING_X + 10, y - FLOOR_H / 2);
