  ctx.fillStyle = "#3a4souls".slice(0,7) === "#3a4so" ? "#3a4152" : "#3a4152";
  ctx.fillRect(BUILDING_X - 10, SLAB_TOP(FLOORS) - FLOOR_H + 20, BUILDING_W + 20, 14);

