  ctx.strokeStyle = "#7a869e";
  ctx.strokeRect(SHAFT_X, SLAB_TOP(FLOORS) - FLOOR_H + 20, SHAFT_W, (FLOORS - 1) * FLOOR_H);

  // waiting passengers on each populated floor
  for (const f of Object.keys(waiting)) {
    const n = waiting[f];
    for (let i = 0; i < n; i++) {
      drawPerson(SHAFT_X - 50 - i * 16, SLAB_TOP(Number(f)), "#e8734a");
    }
  }

  // car: top of car sits on slab of current (fractional) floor
  const c = carRect();
  ctx.fillStyle = "#2f6fb5";
  ctx.fillRect(c.x, c.y, c.w, c.h);

  // passenger inside car drawn before doors so they appear behind panels
  const p = paxPos();
  if (p && p.inCar) drawPerson(p.x, p.y, "#e8734a");

  // doors: two panels sliding apart by open amount
  const open = doorOpenAmount();
  const panelW = (c.w / 2) * (1 - open);
  ctx.fillStyle = "#5aa9ff";
  ctx.fillRect(c.x, c.y + 4, panelW, c.h - 8);
  ctx.fillRect(c.x + c.w - panelW, c.y + 4, panelW, c.h - 8);

  // passenger outside car drawn after doors
  if (p && !p.inCar) drawPerson(p.x, p.y, "#e8734a");

  statusEl.textContent = phase + " | floor " + Math.round(carFloor * 10) / 10;
}

const testMode = new URLSearchParams(location.search).get("test") === "1";
initDispatch();
if (testMode) {
  // run exactly 3 trips synchronously, then report pass.
  // Each trip: idle -> movePickup -> openPickup -> closePickup -> ride -> openDrop -> closeDrop
  let guard = 0;
  while (tripsDone < 4 && phase !== "idle" || (tripsDone < 3 && phase === "idle")) {
    tick(STEP);
    if (++guard > 20000) break; // bounded safety
  }
  draw();
  statusEl.textContent = "ELEVATOR_SMOKE_PASS";
} else {
  let last = performance.now();
  function frame(now) {
    const dt = Math.min(now - last, 100);
    last = now;
    tick(dt);
    draw();
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}
</script>
